// DataQualityServiceHandler is an implementation of the metaxisdata.v1.DataQualityService service.
type DataQualityServiceHandler interface {
	// List rules, newest first.
	ListQualityRules(context.Context, *connect.Request[v1.ListQualityRulesRequest]) (*connect.Response[v1.ListQualityRulesResponse], error)
	// Read one rule, including its current revision and a summary of its most
	// recent result.
	GetQualityRule(context.Context, *connect.Request[v1.GetQualityRuleRequest]) (*connect.Response[v1.QualityRule], error)
	// Create a rule. The rule is validated and compiled before it is stored; a
	// rejected rule is never persisted.
	CreateQualityRule(context.Context, *connect.Request[v1.CreateQualityRuleRequest]) (*connect.Response[v1.QualityRule], error)
	// Create a batch of rules in one call, optionally from the suggestions they
	// came from. Each item is validated and stored independently: a failure is
	// reported in its own result and does not abort the other items.
	BatchCreateQualityRules(context.Context, *connect.Request[v1.BatchCreateQualityRulesRequest]) (*connect.Response[v1.BatchCreateQualityRulesResponse], error)
	// Update a batch of rules in one call. Each item is applied independently:
	// a failure is reported in its own result and does not abort the other items.
	// An item that names a stale revision fails on its own rather than
	// overwriting a concurrent edit.
	BatchUpdateQualityRules(context.Context, *connect.Request[v1.BatchUpdateQualityRulesRequest]) (*connect.Response[v1.BatchUpdateQualityRulesResponse], error)
	// Update a rule. Every semantic edit appends a revision, so a historical
	// result always stays explainable by the definition that produced it.
	UpdateQualityRule(context.Context, *connect.Request[v1.UpdateQualityRuleRequest]) (*connect.Response[v1.QualityRule], error)
	// Delete a rule. The rule, its revisions and results are only archived, never
	// physically removed, so history stays readable.
	DeleteQualityRule(context.Context, *connect.Request[v1.DeleteQualityRuleRequest]) (*connect.Response[emptypb.Empty], error)
	// List the workspace's custom rule templates, newest first. Built-in templates
	// are served by the client catalogue and are not part of this resource.
	ListQualityRuleTemplates(context.Context, *connect.Request[v1.ListQualityRuleTemplatesRequest]) (*connect.Response[v1.ListQualityRuleTemplatesResponse], error)
	// Read one custom rule template.
	GetQualityRuleTemplate(context.Context, *connect.Request[v1.GetQualityRuleTemplateRequest]) (*connect.Response[v1.QualityRuleTemplate], error)
	// Create a custom rule template. A template is a check type and its parameters:
	// target-bound fields (columns, filter) are cleared by the server before it is
	// stored.
	CreateQualityRuleTemplate(context.Context, *connect.Request[v1.CreateQualityRuleTemplateRequest]) (*connect.Response[v1.QualityRuleTemplate], error)
	// Update a custom rule template's title, description, severity, dimension or
	// parameters. The same target-bound fields are cleared.
	UpdateQualityRuleTemplate(context.Context, *connect.Request[v1.UpdateQualityRuleTemplateRequest]) (*connect.Response[v1.QualityRuleTemplate], error)
	// Delete a custom rule template. Checks already created from it are unaffected.
	DeleteQualityRuleTemplate(context.Context, *connect.Request[v1.DeleteQualityRuleTemplateRequest]) (*connect.Response[emptypb.Empty], error)
	// List the workspace's code tables. A list response carries each table's value
	// count but not its values; read one table with GetQualityCodeTable.
	ListQualityCodeTables(context.Context, *connect.Request[v1.ListQualityCodeTablesRequest]) (*connect.Response[v1.ListQualityCodeTablesResponse], error)
	// Read one code table including its values.
	GetQualityCodeTable(context.Context, *connect.Request[v1.GetQualityCodeTableRequest]) (*connect.Response[v1.QualityCodeTable], error)
	// Create a workspace code table. Values are sorted, de-duplicated and capped by
	// the server, so an import is idempotent.
	CreateQualityCodeTable(context.Context, *connect.Request[v1.CreateQualityCodeTableRequest]) (*connect.Response[v1.QualityCodeTable], error)
	// Update a code table's title, description or values. Replacing the values is the
	// import path.
	UpdateQualityCodeTable(context.Context, *connect.Request[v1.UpdateQualityCodeTableRequest]) (*connect.Response[v1.QualityCodeTable], error)
	// Delete a code table. A table still referenced by a rule or a template is
	// refused with FailedPrecondition rather than silently breaking those checks.
	DeleteQualityCodeTable(context.Context, *connect.Request[v1.DeleteQualityCodeTableRequest]) (*connect.Response[emptypb.Empty], error)
	// Validate and compile a rule without saving it: config validation, filter
	// validation and a `LIMIT 0` probe against the target's read-only data
	// source. It writes nothing and creates no run.
	PreviewQualityRule(context.Context, *connect.Request[v1.PreviewQualityRuleRequest]) (*connect.Response[v1.PreviewQualityRuleResponse], error)
	// Execute rules now. One execution is planned per selected rule; the call
	// returns them all as PENDING after queueing them. Clients poll
	// GetQualityExecution for each execution's state and outcome.
	RunQualityRules(context.Context, *connect.Request[v1.RunQualityRulesRequest]) (*connect.Response[v1.RunQualityRulesResponse], error)
	// List executions, newest first.
	ListQualityExecutions(context.Context, *connect.Request[v1.ListQualityExecutionsRequest]) (*connect.Response[v1.ListQualityExecutionsResponse], error)
	// Read one execution: its state, verdict, and the evidence behind it.
	GetQualityExecution(context.Context, *connect.Request[v1.GetQualityExecutionRequest]) (*connect.Response[v1.QualityExecution], error)
	// Read one check's judged values over its recent executions, the band its
	// current thresholds draw, and a threshold suggestion derived from that
	// history. It is a read model over the stored executions: nothing is written,
	// audited or measured against the target database.
	//
	// Only executions that reached a judged verdict (PASS, WARN or FAIL) carry a
	// value, so only those appear as points; a check that has never been judged has
	// no trend rather than a fabricated flat line.
	GetQualityRuleTrend(context.Context, *connect.Request[v1.GetQualityRuleTrendRequest]) (*connect.Response[v1.QualityRuleTrend], error)
	// Export the executions the same filters select as ListQualityExecutions as one
	// CSV document, streamed in slices. This is a file download, not a list: it
	// stops at max_rows and reports the running row count on every slice.
	//
	// Rows are read page by page, so the file is not a consistent snapshot: a row
	// written while the export runs may fall in this file or the next. A stream
	// error means the file is incomplete and must be discarded — only a completed
	// stream is a document.
	//
	// No (google.api.http) annotation: this is a server-streaming method, and the
	// REST gateway cannot carry one. The browser reaches the Connect endpoint
	// directly, the way it does for ExplainSQL.
	ExportQualityExecutions(context.Context, *connect.Request[v1.ExportQualityExecutionsRequest], *connect.ServerStream[v1.ExportQualityDataChunk]) error
	// List runs, newest first. A run is one dispatch batch that belongs to one
	// target: the executions one scheduler tick or one manual request planned for
	// that target. Runs are the batch-level read model the execution directory
	// groups by target; the run itself carries the target and its counts.
	ListQualityRuns(context.Context, *connect.Request[v1.ListQualityRunsRequest]) (*connect.Response[v1.ListQualityRunsResponse], error)
	// Read one run: its target, state, verdict and counts.
	GetQualityRun(context.Context, *connect.Request[v1.GetQualityRunRequest]) (*connect.Response[v1.QualityRun], error)
	// List quality issues, newest first.
	ListQualityIssues(context.Context, *connect.Request[v1.ListQualityIssuesRequest]) (*connect.Response[v1.ListQualityIssuesResponse], error)
	// Read one quality issue.
	GetQualityIssue(context.Context, *connect.Request[v1.GetQualityIssueRequest]) (*connect.Response[v1.QualityIssue], error)
	// Export the issues the same filters select as ListQualityIssues as one CSV
	// document, streamed in slices. This is a file download, not a list: it stops
	// at max_rows and reports the running row count on every slice.
	//
	// Rows are read page by page, so the file is not a consistent snapshot: a row
	// written while the export runs may fall in this file or the next. A stream
	// error means the file is incomplete and must be discarded — only a completed
	// stream is a document.
	//
	// No (google.api.http) annotation, for the same reason as
	// ExportQualityExecutions.
	ExportQualityIssues(context.Context, *connect.Request[v1.ExportQualityIssuesRequest], *connect.ServerStream[v1.ExportQualityDataChunk]) error
	// Acknowledge, resolve or mute one quality issue.
	UpdateQualityIssue(context.Context, *connect.Request[v1.UpdateQualityIssueRequest]) (*connect.Response[v1.QualityIssue], error)
	// List the review queue of model-proposed rule drafts and semantic labels,
	// newest first.
	ListQualitySuggestions(context.Context, *connect.Request[v1.ListQualitySuggestionsRequest]) (*connect.Response[v1.ListQualitySuggestionsResponse], error)
	// Read one queued suggestion. The queue is paged with ListQualitySuggestions;
	// this exists so a deep link can open one draft without reading the pages.
	GetQualitySuggestion(context.Context, *connect.Request[v1.GetQualitySuggestionRequest]) (*connect.Response[v1.QualitySuggestion], error)
	// Accept or reject one queued suggestion. A decision is final: the store
	// refuses a second one.
	UpdateQualitySuggestion(context.Context, *connect.Request[v1.UpdateQualitySuggestionRequest]) (*connect.Response[v1.QualitySuggestion], error)
	// Accept or reject many queued suggestions in one call. Each decision is
	// independent: a failure is reported in its own result and does not abort the
	// rest.
	BatchUpdateQualitySuggestions(context.Context, *connect.Request[v1.BatchUpdateQualitySuggestionsRequest]) (*connect.Response[v1.BatchUpdateQualitySuggestionsResponse], error)
	// Start a background AI drafting job over one or more tables. The call returns
	// as soon as the job is queued: the runner asks the model for each target in
	// turn, and clients poll GetQualitySuggestionJob (or list the jobs) for
	// progress. Queued suggestions appear in the review queue like any other.
	CreateQualitySuggestionJob(context.Context, *connect.Request[v1.CreateQualitySuggestionJobRequest]) (*connect.Response[v1.QualitySuggestionJob], error)
	// Read one drafting job, including per-target progress and the suggestions it
	// queued so far.
	GetQualitySuggestionJob(context.Context, *connect.Request[v1.GetQualitySuggestionJobRequest]) (*connect.Response[v1.QualitySuggestionJob], error)
	// List drafting jobs, newest first.
	ListQualitySuggestionJobs(context.Context, *connect.Request[v1.ListQualitySuggestionJobsRequest]) (*connect.Response[v1.ListQualitySuggestionJobsResponse], error)
	// Ask a drafting job to stop. A pending job is canceled immediately; a running
	// job finishes its current target, marks the rest skipped and ends CANCELED.
	// Suggestions already queued are kept.
	CancelQualitySuggestionJob(context.Context, *connect.Request[v1.CancelQualitySuggestionJobRequest]) (*connect.Response[v1.QualitySuggestionJob], error)
	// Read the raw request and response bodies of one failed target when runtime
	// debug mode captured them. The target's diagnostic carries the correlation id
	// and says whether a body is available; llm_debug_log keeps it for seven days.
	GetQualitySuggestionJobTargetDebug(context.Context, *connect.Request[v1.GetQualitySuggestionJobTargetDebugRequest]) (*connect.Response[v1.GetQualitySuggestionJobTargetDebugResponse], error)
	// List the cached deterministic profiles of columns. Profiles are read-only
	// measurements; there is no get or update.
	ListColumnProfiles(context.Context, *connect.Request[v1.ListColumnProfilesRequest]) (*connect.Response[v1.ListColumnProfilesResponse], error)
	// List the semantic labels asserted on columns.
	ListColumnLabels(context.Context, *connect.Request[v1.ListColumnLabelsRequest]) (*connect.Response[v1.ListColumnLabelsResponse], error)
	// Accept a proposed semantic label or clear the label of one column.
	UpdateColumnLabel(context.Context, *connect.Request[v1.UpdateColumnLabelRequest]) (*connect.Response[v1.UpdateColumnLabelResponse], error)
	// Measure the deterministic statistics of up to 50 columns of one table.
	ProfileColumns(context.Context, *connect.Request[v1.ProfileColumnsRequest]) (*connect.Response[v1.ProfileColumnsResponse], error)
	// Turn a natural-language intent into queued rule drafts.
	SuggestQualityRule(context.Context, *connect.Request[v1.SuggestQualityRuleRequest]) (*connect.Response[v1.SuggestQualityRuleResponse], error)
	// Propose semantic labels for up to 50 columns of one table.
	SuggestColumnLabels(context.Context, *connect.Request[v1.SuggestColumnLabelsRequest]) (*connect.Response[v1.SuggestColumnLabelsResponse], error)
	// Recommend checks for one table from its stored column profiles. The pass is
	// deterministic: it needs no model, no provider configuration and no connection
	// to the target database. Like every other generation pass it queues PENDING
	// rule drafts only; a reviewer still decides which drafts become checks. The
	// request refuses columns without a fresh profile, pointing at ProfileColumns.
	RecommendQualityChecks(context.Context, *connect.Request[v1.RecommendQualityChecksRequest]) (*connect.Response[v1.RecommendQualityChecksResponse], error)
	// Explain one failed execution as a stream of hypotheses.
	//
	// No (google.api.http) annotation: this is a server-streaming method, and the
	// REST gateway cannot carry one. The browser reaches the Connect endpoint
	// directly, the way it does for ExplainSQL.
	ExplainQualityExecution(context.Context, *connect.Request[v1.ExplainQualityExecutionRequest], *connect.ServerStream[v1.ExplainQualityExecutionResponse]) error
	// Read the workspace's quality summary: how many rules and issues exist, how
	// the last day went, and the per-day tallies the overview chart draws.
	GetQualityOverview(context.Context, *connect.Request[v1.GetQualityOverviewRequest]) (*connect.Response[v1.QualityOverview], error)
	// Read how much of the data other assets consume is watched. Unlike the
	// overview's coverage, whose denominator is every monitorable registry object,
	// this answers a consumption question: of the assets whose lineage shows
	// another object reading them, how many have an enabled check? The two ratios
	// have different denominators and are deliberately not combined.
	//
	// It is a separate read because answering it costs one grouped scan of the
	// lineage table, which the overview must not pay on every load.
	GetQualityConsumptionCoverage(context.Context, *connect.Request[v1.GetQualityConsumptionCoverageRequest]) (*connect.Response[v1.GetQualityConsumptionCoverageResponse], error)
	// List the targets (tables or views) that have quality rules, one row per
	// target. The counts, the worst latest result and the pending draft tally are
	// aggregated by the database, so the directory does not page through every
	// rule to answer "which table needs attention?".
	ListQualityTargets(context.Context, *connect.Request[v1.ListQualityTargetsRequest]) (*connect.Response[v1.ListQualityTargetsResponse], error)
	// Export the targets the same filters select as ListQualityTargets as one CSV
	// document, streamed in slices. This is a file download, not a list: it stops
	// at max_rows and reports the running row count on every slice.
	//
	// Rows are read page by page, so the file is not a consistent snapshot: a row
	// written while the export runs may fall in this file or the next. A stream
	// error means the file is incomplete and must be discarded — only a completed
	// stream is a document.
	//
	// No (google.api.http) annotation, for the same reason as
	// ExportQualityExecutions.
	ExportQualityTargets(context.Context, *connect.Request[v1.ExportQualityTargetsRequest], *connect.ServerStream[v1.ExportQualityDataChunk]) error
	// Read one target's workspace: its rules (with their latest results), the
	// unresolved issues and the target's columns, in one call. AI drafts are not
	// part of the response (reading them needs the suggest permission). The target
	// is named by GUID because a target is not a resource of its own.
	GetQualityTarget(context.Context, *connect.Request[v1.GetQualityTargetRequest]) (*connect.Response[v1.GetQualityTargetResponse], error)
	// Explain a target's quality state by its lineage: the assets its data
	// reaches downstream, and the upstream targets whose checks failed or whose
	// structure changed in the window before a reference instant. Both lists are
	// bounded walks over the recorded lineage, so a target with no recorded edges
	// has no impact to report — which is not the same as having no consumers.
	GetQualityTargetImpact(context.Context, *connect.Request[v1.GetQualityTargetImpactRequest]) (*connect.Response[v1.GetQualityTargetImpactResponse], error)
	// Acknowledge that a target's structure changed and re-baseline its checks.
	// Every non-archived check whose saved structure snapshot differs from the
	// target's current fingerprint gets the current fingerprint, which clears the
	// schema-changed signal. The checks themselves are untouched: re-baselining is
	// a fact about which shape the checks were reviewed against, not a change to
	// their definition, so it does not write a rule revision. Idempotent: a second
	// call with nothing to do returns zero.
	AcknowledgeQualityTargetSchema(context.Context, *connect.Request[v1.AcknowledgeQualityTargetSchemaRequest]) (*connect.Response[v1.AcknowledgeQualityTargetSchemaResponse], error)
	// Render one target's quality report as a self-contained HTML document: the
	// current state, the recent trend, the checks, the unresolved problems, a
	// capped sample summary and the monitoring basis. The document carries its own
	// styles and chart and loads nothing external, so it can be forwarded as a
	// file. The export is audited because it is a bulk read of quality evidence.
	//
	// The report includes real sample values from failed checks (capped), so it is
	// a wider disclosure than the rules.list permission usually implies; the
	// document itself warns about forwarding it. Its HTML body never enters the
	// audit ledger (see ExportQualityReportResponse.html_content).
	ExportQualityReport(context.Context, *connect.Request[v1.ExportQualityReportRequest]) (*connect.Response[v1.ExportQualityReportResponse], error)
	// Update one target's schedule: how often its enabled checks run. Scheduling
	// is per target, so this replaces the per-check schedule; a change takes
	// effect from the next slot and never runs the target immediately.
	UpdateQualityTargetSchedule(context.Context, *connect.Request[v1.UpdateQualityTargetScheduleRequest]) (*connect.Response[v1.QualityTargetSchedule], error)
	// Read one target's schedule without the target's rules, results and issues.
	// A rule lifecycle change can move the target's next run; the workspace re-reads
	// just this instead of the whole target after every check edit.
	GetQualityTargetSchedule(context.Context, *connect.Request[v1.GetQualityTargetScheduleRequest]) (*connect.Response[v1.QualityTargetSchedule], error)
	// Read one target's contract: its target-level defaults, the published version,
	// and whether the live rules differ from that snapshot.
	GetQualityContract(context.Context, *connect.Request[v1.GetQualityContractRequest]) (*connect.Response[v1.QualityContract], error)
	// ListQualityPlans lists the read-only monitoring plan projection for every
	// target with live rules. It is the directory the plan write path will grow
	// from; it does not write anything.
	ListQualityPlans(context.Context, *connect.Request[v1.ListQualityPlansRequest]) (*connect.Response[v1.ListQualityPlansResponse], error)
	// ListQualityCoverageGaps flattens the plan projection to the unsatisfied
	// declared coverage: one row per target property that a live rule does not
	// implement. Read-only, like ListQualityPlans.
	ListQualityCoverageGaps(context.Context, *connect.Request[v1.ListQualityCoverageGapsRequest]) (*connect.Response[v1.ListQualityCoverageGapsResponse], error)
	// Update the target-level defaults. The filter is ANDed into every rule on the
	// target at compile time; the default severity only seeds newly authored rules
	// and never rewrites an existing rule. The target's schedule is updated through
	// UpdateQualityTargetSchedule.
	UpdateQualityContract(context.Context, *connect.Request[v1.UpdateQualityContractRequest]) (*connect.Response[v1.QualityContract], error)
	// Publish the live rules and settings as the target's next contract version.
	// Republishing an unchanged contract is a no-op that returns the existing
	// version (no_changes=true).
	PublishQualityContract(context.Context, *connect.Request[v1.PublishQualityContractRequest]) (*connect.Response[v1.PublishQualityContractResponse], error)
	// Record one investigation: an agent's hypotheses, deterministic evidence
	// references, verdict and cost on one event. It never changes the check's verdict
	// or an issue's state. The agent needs autonomy enabled.
	CreateQualityInvestigation(context.Context, *connect.Request[v1.CreateQualityInvestigationRequest]) (*connect.Response[v1.QualityInvestigation], error)
	// Read one investigation.
	GetQualityInvestigation(context.Context, *connect.Request[v1.GetQualityInvestigationRequest]) (*connect.Response[v1.QualityInvestigation], error)
	// List investigations, newest first.
	ListQualityInvestigations(context.Context, *connect.Request[v1.ListQualityInvestigationsRequest]) (*connect.Response[v1.ListQualityInvestigationsResponse], error)
	// Read the WS2 action catalog and how the autonomy policy would decide each action
	// for an agent right now. Read-only: it exposes the policy, it does not change it.
	GetQualityActionPolicy(context.Context, *connect.Request[v1.GetQualityActionPolicyRequest]) (*connect.Response[v1.QualityActionPolicy], error)
	// Record one memory: an asset fact, a decision with its structured reason, or an
	// event. An agent may write asset facts directly; a decision or an event it writes
	// stays PROPOSED until a person confirms it.
	CreateQualityMemory(context.Context, *connect.Request[v1.CreateQualityMemoryRequest]) (*connect.Response[v1.QualityMemory], error)
	// List memories. Expired confirmations read as EXPIRED; superseded ones stay
	// visible for the correction path.
	ListQualityMemories(context.Context, *connect.Request[v1.ListQualityMemoriesRequest]) (*connect.Response[v1.ListQualityMemoriesResponse], error)
	// Confirm or reject a PROPOSED memory. A person's judgment is what turns it into
	// knowledge; nothing else confirms it.
	ConfirmQualityMemory(context.Context, *connect.Request[v1.ConfirmQualityMemoryRequest]) (*connect.Response[v1.QualityMemory], error)
	// Delete a memory. Administrator cleanup; the row is kept out of reads, and the
	// audit row records who removed it.
	DeleteQualityMemory(context.Context, *connect.Request[v1.DeleteQualityMemoryRequest]) (*connect.Response[emptypb.Empty], error)
	// Write the target's plan declaration without touching its settings. This is the
	// one write an agent principal may make; an agent call is refused while the
	// workspace kill switch or the agent itself is disabled.
	StageQualityPlan(context.Context, *connect.Request[v1.StageQualityPlanRequest]) (*connect.Response[v1.QualityContract], error)
	// Create a batch of typed changes against one target. It stays PROPOSED until a
	// person decides; creating it changes nothing on the target. An agent principal
	// may only create PROPOSED requests, and only while autonomy is enabled.
	CreateQualityChangeRequest(context.Context, *connect.Request[v1.CreateQualityChangeRequestRequest]) (*connect.Response[v1.QualityChangeRequest], error)
	// Read one change request, with its items and per-item results.
	GetQualityChangeRequest(context.Context, *connect.Request[v1.GetQualityChangeRequestRequest]) (*connect.Response[v1.QualityChangeRequest], error)
	// List change requests, newest first.
	ListQualityChangeRequests(context.Context, *connect.Request[v1.ListQualityChangeRequestsRequest]) (*connect.Response[v1.ListQualityChangeRequestsResponse], error)
	// Create an agent principal and return its bearer token once. The agent is an
	// independent principal whose only workspace role is the quality agent role; its
	// token is a normal access token for that principal, so disabling the agent makes
	// every token it issued unusable. Administrator only.
	CreateQualityAgent(context.Context, *connect.Request[v1.CreateQualityAgentRequest]) (*connect.Response[v1.CreateQualityAgentResponse], error)
	// List the workspace's agent principals, without tokens.
	ListQualityAgents(context.Context, *connect.Request[v1.ListQualityAgentsRequest]) (*connect.Response[v1.ListQualityAgentsResponse], error)
	// Disable an agent principal. Its tokens stop authenticating immediately; the
	// agent row stays for the audit trail.
	DisableQualityAgent(context.Context, *connect.Request[v1.DisableQualityAgentRequest]) (*connect.Response[v1.QualityAgent], error)
	// Rotate an agent's bearer token: mint a new one and invalidate every token
	// minted before this call. The token is returned once.
	RotateQualityAgentToken(context.Context, *connect.Request[v1.RotateQualityAgentTokenRequest]) (*connect.Response[v1.RotateQualityAgentTokenResponse], error)
	// Approve or reject a change request. Approving applies each item through its
	// existing path and returns a result per item; rejecting records the structured
	// reasons. A stale base version expires the request instead of rebasing it.
	DecideQualityChangeRequest(context.Context, *connect.Request[v1.DecideQualityChangeRequestRequest]) (*connect.Response[v1.QualityChangeRequest], error)
	// List the target's published contract versions, newest first.
	ListQualityContractRevisions(context.Context, *connect.Request[v1.ListQualityContractRevisionsRequest]) (*connect.Response[v1.ListQualityContractRevisionsResponse], error)
	// Read one published contract version with its ordered checks, so a client can
	// show a diff without downloading every version.
	GetQualityContractRevision(context.Context, *connect.Request[v1.GetQualityContractRevisionRequest]) (*connect.Response[v1.GetQualityContractRevisionResponse], error)
	// Read today's data quality LLM usage and the effective limits (the workspace
	// settings, with server defaults resolved). The counters are process state: a
	// restart resets them and they roll over at 00:00 UTC.
	GetQualityLLMUsage(context.Context, *connect.Request[v1.GetQualityLLMUsageRequest]) (*connect.Response[v1.QualityLLMUsage], error)
}

